// Normalize Lark Base automation / event payload into a canonical shape.
// Lark Base automation webhook -> fields at $json.record.fields
// Lark Open Platform event       -> fields at $json.event.record.fields
const body = $input.first().json;
const rec  = body.record ?? body.event?.record ?? body;
const fields = rec.fields ?? body.fields ?? {};

const answers = {};
for (const k of Object.keys(fields)) {
  if (/^q\d+$/i.test(k)) answers[k.toLowerCase()] = String(fields[k] ?? '');
}

return [{
  json: {
    submission_id: rec.record_id ?? body.record_id ?? body.event_id ?? crypto.randomUUID(),
    name:  fields.name  ?? fields.Name  ?? '',
    email: fields.email ?? fields.Email ?? '',
    answers,
  }
}];

// Stub answer key loader. In production replace this node with an
// HTTP Request / Lark Base read that returns the same JSON shape.
return [{
  json: {
    version: 1,
    passing_percent: 75,
    questions: [
      { id: 'q1', type: 'exact',    prompt: 'Default PostgreSQL port?', expected: '5432', weight: 1, normalize: 'trim_lower' },
      { id: 'q2', type: 'exact',    prompt: 'HTTP status for Not Found?', expected: '404', weight: 1, normalize: 'trim_lower' },
      {
        id: 'q3', type: 'scenario', weight: 3, max_score: 5,
        prompt: 'A customer reports the app is slow only at 9am. Walk through your debugging approach.',
        expected_points: [
          'checks traffic or load spike at 9am',
          'looks at logs and metrics around that window',
          'considers scheduled jobs or cron',
          'forms a hypothesis before making changes'
        ],
        required_keywords: ['logs', 'metrics']
      }
    ]
  }
}];

const key = $('Load answer key').first().json;
const submission = $('Normalize submission').first().json;

return key.questions.map(q => ({
  json: {
    submission_id:   submission.submission_id,
    name:            submission.name,
    email:           submission.email,
    passing_percent: key.passing_percent,
    rubric_version:  key.version,
    question:        q,
    answer:         (submission.answers?.[q.id] ?? '').toString(),
  }
}));

const { question, answer } = $json;
const norm = s => question.normalize === 'trim_lower'
  ? String(s).trim().toLowerCase()
  : String(s).trim();

const match = norm(answer) === norm(question.expected ?? '');
return [{
  json: {
    ...$json,
    per_question: {
      id: question.id,
      type: 'exact',
      score: match ? question.weight : 0,
      max:   question.weight,
      feedback: match ? 'Correct.' : 'Incorrect.'
    }
  }
}];

// Parse LLM JSON + apply keyword floor + compute weighted score.
const item = $input.first().json;
const question = item.question;
const answer   = item.answer;

// LLM response shape varies slightly by n8n version.
let raw = item.message?.content ?? item.choices?.[0]?.message?.content ?? item.text ?? '';
let out;
try { out = typeof raw === 'string' ? JSON.parse(raw) : raw; }
catch { out = { score: 0, reasoning: 'Malformed LLM output, defaulted to 0.', missing_points: [], keywords_found: [] }; }

const maxQ = question.max_score ?? 5;
let score = Math.max(0, Math.min(maxQ, Number(out.score) || 0));

if (question.required_keywords?.length) {
  const lower = (answer || '').toLowerCase();
  const missing = question.required_keywords.filter(k => !lower.includes(k.toLowerCase()));
  if (missing.length) score = Math.min(score, Math.floor(maxQ / 2));
}

const weighted = (score * question.weight) / maxQ;
return [{
  json: {
    ...item,
    per_question: {
      id: question.id,
      type: 'scenario',
      score: weighted,
      max:   question.weight,
      raw_score: score,
      max_raw:   maxQ,
      feedback:  out.reasoning ?? '',
      missing:   out.missing_points ?? [],
    }
  }
}];

const items = $input.all().map(i => i.json.per_question);
const sub   = $('Normalize submission').first().json;
const key   = $('Load answer key').first().json;

const score = items.reduce((s, q) => s + q.score, 0);
const max   = items.reduce((s, q) => s + q.max,   0);
const percent = max > 0 ? Math.round((score / max) * 1000) / 10 : 0;
const pass = percent >= key.passing_percent;

return [{
  json: {
    submission_id: sub.submission_id,
    name:  sub.name,
    email: sub.email,
    answers: sub.answers,
    per_question: items,
    score, max, percent,
    result: pass ? 'Pass' : 'Fail',
    rubric_version: key.version,
    graded_at: new Date().toISOString(),
  }
}];

const j = $json;
return [{
  json: {
    submission_id: j.submission_id,
    name: j.name,
    email: j.email,
    answers_json: JSON.stringify(j.answers),
    per_q_json:   JSON.stringify(j.per_question),
    score: j.score,
    max_score: j.max,
    percent: j.percent,
    result: j.result,
    rubric_version: j.rubric_version,
    graded_at: j.graded_at
  }
}];
